function CountIntegers(values: seq<object>) : int
    requires forall i :: 0 <= i < |values| ==> (values[i] is int or values[i] is not int)
    ensures CountIntegers(values) == |{ x | x in values, x is int }|
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= i <= |values|
        invariant count == |{ x | j in 0..i, x := values[j], x is int }|
    {
        if (values[i] is int) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

